lines = [l.rstrip("\n") for l in io.open(MISS, encoding="utf-8") if l.strip()]
keys = [l.split("\t")[1] for l in lines[1:]]
if len(keys) == 29:
    pairs = list(zip(keys, TR))
elif len(keys) == 5:
    pairs = [(keys[i], TR[idx]) for i, idx in enumerate([23, 24, 25, 27, 28])]
else:
    raise SystemExit('unexpected missing keys: %d' % len(keys))
for rec in EXTRA:
    pairs.append((rec["zh"], (rec["en"], rec["vi"], rec["th"], rec["id"], rec["ms"])))

codes = ["en", "vi", "th", "id", "ms"]
for ci, code in enumerate(codes):
    fp = os.path.join(ROOT, "prototype", "data", "i18n-%s.js" % code)
    s = io.open(fp, encoding="utf-8").read()
    idx = s.rfind("};")
    head, tail = s[:idx].rstrip(), s[idx:]
    entries = []
    for k, vals in pairs:
        if re.search(r'^\s*' + re.escape(json.dumps(k, ensure_ascii=False)) + r'\s*:', s, re.M):
            continue
        entries.append("  " + json.dumps(k, ensure_ascii=False) + ": " + json.dumps(vals[ci], ensure_ascii=False))
    if entries:
        head = head + ",\n" + ",\n".join(entries)
    io.open(fp, "w", encoding="utf-8", newline="\n").write(head + "\n" + tail)
    print(code, "added", len(entries))
